function forecastScoreGuide20261012(axes){return `<details class="forecast-score-guide"><summary>100点評価の内訳</summary><p>点数は当サイトの相対的な戦力評価です。勝率ではありません。</p><ul>${axes.map(([name,max])=>`<li>${name} <strong>${max}点</strong></li>`).join('')}</ul></details>`;}
function forecastTeamVisual20261012(name){
 const colors={
 '青山学院大学':['青','#25a56a','#fff'],'國學院大學':['國','#8e2b68','#fff'],
 '中央大学':['C','#c8102e','#fff'],'早稲田大学':['早','#8b1e3f','#fff'],
 '駒澤大学':['駒','#8f82bc','#241b42'],'順天堂大学':['順','#342b4f','#fff'],
 '創価大学':['創','#174ea6','#fff'],'帝京大学':['帝','#e43d30','#fff'],
 '城西大学':['城','#f1c40f','#173250'],'日本大学':['日','#d71920','#fff'],
 '中央学院大学':['中院','#6f2c91','#fff'],'東海大学':['東海','#1698d1','#102b42'],
 '神奈川大学':['神','#243f8f','#fff'],'東洋大学':['東洋','#273c80','#fff'],
 '山梨学院大学':['山学','#005aa9','#fff'],'大東文化大学':['大東','#71b644','#173250']
 };
 return colors[name]||[name.slice(0,1),'#49657f','#fff'];
}
function forecastScoreCards20261012(rows,axes){return `<div class="forecast-rank-grid">${rows.map((r,i)=>{
 const [icon,color,ink]=forecastTeamVisual20261012(r.team),score=r.parts.reduce((a,b)=>a+b,0);
 return `<article class="forecast-rank-card" style="--forecast-team-color:${color};--forecast-team-ink:${ink}">
 <div class="forecast-rank-head"><span class="forecast-place">${i+1}<small>位</small></span>
 <div class="forecast-team-identity"><span class="forecast-team-icon" aria-hidden="true">${icon}</span><h3>${r.team}</h3></div>
 <strong class="forecast-points">${score}<small>/100点</small></strong></div>
 <progress class="forecast-total-gauge" max="100" value="${score}" aria-label="${r.team} 総合評価 ${score}点"></progress>
 <p>${r.note}</p><details><summary>評価点の内訳</summary><div class="forecast-breakdown">${axes.map(([name,max],j)=>`<div><span>${name}</span><strong>${r.parts[j]} / ${max}</strong><progress max="${max}" value="${r.parts[j]}" aria-label="${name} ${r.parts[j]}点"></progress></div>`).join('')}</div></details></article>`;
 }).join('')}</div>`;}

function forecastSources20261012(){return `<p class="forecast-sources"><a href="https://www.izumo-ekiden.jp/assets/pdf/record2026.pdf" target="_blank" rel="noopener">出雲公式結果</a> ／ <a href="${zennihonEntries2026.source}" target="_blank" rel="noopener">全日本登録16名</a> ／ <a href="https://www.joqr.co.jp/news/article/183863/" target="_blank" rel="noopener">青山学院・原監督</a> ／ <a href="https://www.joqr.co.jp/news/article/183864/" target="_blank" rel="noopener">國學院・前田監督</a> ／ <a href="https://www.joqr.co.jp/news/article/183862/" target="_blank" rel="noopener">順天堂・長門監督</a></p>`;}
function forecastPb20261012(team,name){const resolver=window.currentAthletePbResolver;return (resolver?.currentRows?.(team)||[]).find(r=>zenEntryKey2026(r.name)===zenEntryKey2026(name))||(forecastPbSnapshot20261012[team]||[]).find(r=>zenEntryKey2026(r.name)===zenEntryKey2026(name));}
function forecastForm20261012(team,name){const db=window.threeEkidenSectionsDB?.izumo?.[2026]?.sections||forecastIzumoSnapshot20261012;for(const [section,rows] of Object.entries(db)){const r=rows.find(r=>r.team===team&&zenEntryKey2026(r.athlete)===zenEntryKey2026(name));if(r)return `出雲${section}区 ${r.rank}位・${r.time}${r.record?'（区間新）':''}`;}return '';}
function forecastSectionReason20261012(team,name,index){const pb=forecastPb20261012(team,name),form=forecastForm20261012(team,name);const roles=["集団での位置取りと長い1区の巡航を重視。","早い段階で差を作るため、速度と駅伝の対応力を重視。","11.9kmを高い速度で押す役割。","序盤の勢いを保ち、中盤へ確実につなぐ役割。","12.4kmの持続力と単独走への対応を重視。","後半の長区間へ渡す前の粘りを重視。","17.6kmの起伏を含む長いロードへの対応を重視。","19.7kmを任せる長距離の実績とエースとしての再現性を重視。"];let record='';if(index>=6)record=pb?.half?`ハーフPB ${pb.half}。`:'長区間の候補としての予想です。';else if(pb?.pb10000)record=`10000m PB ${pb.pb10000}。`;else if(pb?.pb5000)record=`5000m PB ${pb.pb5000}。`;return `${form?form+'。':''}${record}${roles[index]}`;}
function zennihonPredictionTemplate(){const rankings=zennihonScoreRows20261012;return `<section class="container page forecast-refresh-page"><div class="page-header"><h1>2026 全日本大学駅伝予想</h1><p>10月12日更新。出雲の公式結果、10月8日確定の登録16名、ロードの実績を反映した予想です。</p></div><h2>関東15大学の順位予想・総合戦力点</h2><p>関東出場校内の順位です。出雲未出場校も既存のロード実戦・登録戦力で評価し、未出場だけでは減点しません。</p>${forecastScoreGuide20261012(zennihonScoreAxes20261012)}${forecastScoreCards20261012(rankings,zennihonScoreAxes20261012)}<h2 class="forecast-orders-heading">関東15大学 区間予想</h2><p>大学名をタップすると、全8区間の予想・配置理由と公式エントリー16名が開きます。</p>${rankings.map((r,j)=>{const names=zennihonOrders2026[r.team],roster=zennihonEntries2026.teams[r.team];return `<details class="forecast-team-card" id="zen-forecast-${j}"><summary><strong>${r.team}</strong><span>8区間・登録16名</span></summary><p class="forecast-team-note">${r.note}</p><div class="forecast-section-grid">${names.map((name,i)=>`<article class="forecast-section-card"><h3>${i+1}区 <small>${ekidenCourse2026.zennihon[i][0].toFixed(1)}km</small></h3><strong>${name}</strong><p>${forecastSectionReason20261012(r.team,name,i)}</p></article>`).join('')}</div><h3 class="forecast-roster-heading">公式エントリー16名・学年</h3><ol class="forecast-roster">${roster.map(p=>{const i=names.findIndex(n=>zenEntryKey2026(n)===zenEntryKey2026(p.name));return `<li><strong>${p.name}</strong><span>${p.grade}年</span><small>${i>=0?`区間予想：${i+1}区`:'区間予想：未配置'}</small></li>`;}).join('')}</ol><p><a href="${zennihonEntries2026.source}" target="_blank" rel="noopener">公式確定名簿</a></p></details>`;}).join('')}<details class="forecast-course-guide"><summary>全8区間のコース特徴</summary>${courseGuide2026('zennihon')}</details><p class="notice">区間配置は当サイトの予想です。正式な区間メンバーは10月29日発表予定で、当日変更もあります。</p>${forecastSources20261012()}</section>`;}


